pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address starter, uint256 drugs) public {
        vm.assume(starter != address(0));
        vm.deal(starter, 1 ether);

        bool ok;
        vm.prank(starter);
        try c.seedMarket{value: 1 wei}(drugs) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.initialized());
        } else {
            assertTrue(true);
        }
    }
}
